// ==========================================
// 1. 在这里维护你的订阅源（干净清爽，只需填 name 和 url）
// ==========================================
const feeds = [
  { 
    name: "财联社", 
    url: "https://rss.xujwx.xyz/cls/telegraph?format=json" 
  },
  { 
    name: "华尔街见闻", 
    url: "https://rss.xujwx.xyz/wallstreetcn/live/global?format=json" 
  },
  { 
    name: "金十数据", 
    url: "https://rss.xujwx.xyz/jin10/:important?format=json" 
  },
];

// ==========================================
// 2. 自动转换（这部分代码永远不需要动）
// ==========================================
return feeds.map(item => {
  return { json: item };
});

const hoursAgo = 1;
const cutoffTime = new Date(new Date().getTime() - hoursAgo * 60 * 60 * 1000);
const allFeeds = $input.all();
let allItems = [];

for (const feed of allFeeds) {
  let sourceData = feed.json.data || feed.json.items || feed.json;
  if (typeof sourceData === 'string') {
    try { sourceData = JSON.parse(sourceData); } 
    catch (e) { continue; }
  }

  const items = Array.isArray(sourceData) ? sourceData : (sourceData.items || []);
  if (!Array.isArray(items)) continue;

  for (const item of items) {
    const timeString = item.date_published || item.pubDate || item.created_at || item.time;
    const itemTime = new Date(timeString);

    if (!isNaN(itemTime.getTime()) && itemTime > cutoffTime) {
      // 提取内容并剔除 HTML 标签，防止 AI token 爆炸
      let rawContent = item.summary || item.content_html || item.description || "";
      let cleanContent = rawContent.replace(/<[^>]+>/g, '').substring(0, 300);

      allItems.push({
        title: item.title || "无标题",
        content: cleanContent,
        url: item.url || item.link || "",
        time: itemTime.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })
      });
    }
  }
}

// 简单去重
const uniqueMap = new Map();
for (const item of allItems) {
  if (item.title && !uniqueMap.has(item.title)) {
    uniqueMap.set(item.title, item);
  }
}
const uniqueItems = Array.from(uniqueMap.values());

// 打包成一个整体输出
return { 
  json: { 
    news_list: uniqueItems, 
    total_count: uniqueItems.length 
  } 
};

// 引入 Node.js 原生加密模块（n8n 默认允许引用）
const crypto = require('crypto');

// ⚠️ 在这里填入你的钉钉 Token 和 SEC 密钥
const accessToken = 'c8f75452059bd89fa1010da170936e7360168e22ea38eec5efba57356ffbfcfe'; 
const secret = 'SECaabc74a6447a606341409e631803d3030e62d737755237cba4f56f229f87a191';

// 遍历流经此节点的所有数据项
for (const item of $input.all()) {
  // 1. 获取当前毫秒时间戳
  const timestamp = new Date().getTime();

  // 2. 拼接待签名字符串
  const stringToSign = timestamp + '\n' + secret;

  // 3. 计算 HMAC-SHA256 加密并转为 Base64
  const hash = crypto.createHmac('sha256', secret).update(stringToSign).digest('base64');

  // 4. 对生成的 Base64 字符串进行 URL 编码
  const sign = encodeURIComponent(hash);

  // 5. 将完整的 URL 附加到当前数据流中，命名为 webhook_url
  item.json.webhook_url = `https://oapi.dingtalk.com/robot/send?access_token=${accessToken}&timestamp=${timestamp}&sign=${sign}`;
}

// 返回处理后的数据
return $input.all();
